SELECT date,
       SUM(pv)  AS pv,
       SUM(uv)  AS uv,
       SUM(uip) AS uip
FROM t_link_access_stats
WHERE full_short_url = #{fullShortUrl}
  AND gid = #{gid}
  AND del_flag = 0
  AND date BETWEEN #{startDate} AND #{endDate}
GROUP BY full_short_url, gid, date;

SELECT date,
       SUM(pv)  AS pv,
       SUM(uv)  AS uv,
       SUM(uip) AS uip
FROM t_link_access_stats
WHERE gid = #{gid}
  AND date BETWEEN #{startDate} and #{endDate}
GROUP BY gid, date;

SELECT hour,
       SUM(pv)  AS pv,
       SUM(uv)  AS uv,
       SUM(uip) AS uip
FROM t_link_access_stats
WHERE full_short_url = #{fullShortUrl}
  AND gid = #{gid}
  AND del_flag = 0
  AND date BETWEEN #{startDate} AND #{endDate}
GROUP BY full_short_url, gid, hour;

SELECT hour,
       SUM(pv) AS pv
FROM t_link_access_stats
WHERE gid = #{gid}
  AND date BETWEEN #{startDate} and #{endDate}
GROUP BY gid, hour;

SELECT weekday,
       SUM(pv)  AS pv,
       SUM(uv)  AS uv,
       SUM(uip) AS uip
FROM t_link_access_stats
WHERE full_short_url = #{fullShortUrl}
  AND gid = #{gid}
  AND date BETWEEN #{startDate} AND #{endDate}
  AND del_flag = 0
GROUP BY full_short_url, gid, weekday;

SELECT weekday,
       SUM(pv) AS pv
FROM t_link_access_stats
WHERE gid = #{gid}
  AND date BETWEEN #{startDate} and #{endDate}
GROUP BY gid, weekday;
